  /// [icon] 的实心（FILL=1）版本：选中态 / 激活态用。非语义图标原样返回。
  static IconData filled(IconData icon) {
    if (icon.fontFamily != kFushiSymbolsFontFamily) return icon;
    return _filled[icon.codePoint] ?? icon;
  }

  /// [filled] 为 true 时取实心版，否则原样（导航项 / 开关按钮常用写法）。
  static IconData resolve(IconData icon, {required bool filled}) =>
      filled ? FushiIcons.filled(icon) : icon;

